import {describe, expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

function createMockProvider(response: string): AIProvider {
  return {
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: response};
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

describe('ChatOrchestrator - beforeSession failure', () => {
  it('should call onError and afterSession when beforeSession throws', async () => {
    const error = new Error('beforeSession failed');
    let onErrorCalled = false;
    let afterSessionCalled = false;

    const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {
      hooks: {
        beforeSession: async () => {
          throw error;
        },
        onError: async () => {
          onErrorCalled = true;
        },
        afterSession: async () => {
          afterSessionCalled = true;
        },
      },
    });

    const session = createSession('hello');
    // We use processMessage which calls processMessageStream and collects text
    await expect(orchestrator.processMessage(session)).rejects.toThrow('beforeSession failed');

    expect(onErrorCalled).toBe(true);
    expect(afterSessionCalled).toBe(true);
  });
});

